/**
 * Signals in message LeanEstimate.
 *
 * rt-core EKF (Layer 2) lean estimate for the cornering decision. Safety range, E2E protected.
 *
 * All signal values are as on the CAN bus.
 */
struct platform_lean_estimate_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t e2_e_crc;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t e2_e_counter;

    /**
     * 0 = NOT_AVAILABLE so an all-zero payload is never valid. Codes 5-15 are invalid. Whether CLAMPED/DEFAULT_FALLBACK may be used by the safety decision is open (Q-002).
     *
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t lean_status;

    /**
     * Roll angle, ISO 8855: positive = right side down.
     *
     * Range: -9000..9000 (-90..90 deg)
     * Scale: 0.01
     * Offset: 0
     */
    int16_t lean_angle;

    /**
     * Roll rate, ISO 8855: positive = rolling to the right.
     *
     * Range: -30000..30000 (-300..300 deg/s)
     * Scale: 0.01
     * Offset: 0
     */
    int16_t lean_rate;

    /**
     * EKF confidence in LEAN_ANGLE, 0 = none, 100 = full.
     *
     * Range: 0..100 (0..100 %)
     * Scale: 1
     * Offset: 0
     */
    uint8_t lean_angle_quality;
};

/**
 * Signals in message CorneringParamEstimate.
 *
 * rt-core EKF (Layer 2) cornering parameters, clamped to physical ranges by rt-core. Safety range, E2E protected.
 *
 * All signal values are as on the CAN bus.
 */
struct platform_cornering_param_estimate_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t e2_e_crc;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t e2_e_counter;

    /**
     * 0 = NOT_AVAILABLE so an all-zero payload is never valid. Codes 5-15 are invalid. Use of CLAMPED/DEFAULT_FALLBACK values is open (Q-002).
     *
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t param_status;

    /**
     * Estimated tyre-road friction coefficient (mu). The DBC range is a transport range, not a safety ceiling: safety-node applies its own fixed ceiling.
     *
     * Range: 0..150 (0..1.5 -)
     * Scale: 0.01
     * Offset: 0
     */
    uint8_t friction_coeff;

    /**
     * Estimated vehicle + rider + load mass. Transport range only; physically implausible values (e.g. 0) mean INVALID at the consumer, never clamped (plausibility limits to be set with Q-002).
     *
     * Range: 0..10000 (0..1000 kg)
     * Scale: 0.1
     * Offset: 0
     */
    uint16_t total_mass;

    /**
     * Estimated centre-of-gravity height above ground. Transport range only; implausible values (e.g. 0) mean INVALID at the consumer.
     *
     * Range: 0..2000 (0..2 m)
     * Scale: 0.001
     * Offset: 0
     */
    uint16_t cog_height;

    /**
     * EKF confidence in the parameters, 0 = none, 100 = full.
     *
     * Range: 0..100 (0..100 %)
     * Scale: 1
     * Offset: 0
     */
    uint8_t param_quality;
};

